package com.ftk.tpip.control.api.catalog;
import com.ftk.tpip.catalog.domain.model.*;import com.ftk.tpip.control.application.catalog.CatalogHierarchyApplicationService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.net.URI;import java.time.Instant;import java.util.List;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController @RequestMapping("/control/v1/capabilities") public class CanonicalCapabilityController{private final CatalogHierarchyApplicationService s;public CanonicalCapabilityController(CatalogHierarchyApplicationService s){this.s=s;}
@PostMapping public ResponseEntity<Response> create(@Valid@RequestBody Create r,@RequestHeader("X-Operator")@NotBlank@Size(max=100)String a){var c=s.createCapability(r.domainId,r.capabilityCode,r.capabilityName,r.description,r.ownerCode,a);return ResponseEntity.created(URI.create("/control/v1/capabilities/"+c.id())).body(Response.from(c));}@GetMapping("/{id}")public Response get(@PathVariable@Min(1)long id){return Response.from(s.getCapability(id));}@GetMapping public Page list(@RequestParam(required=false)@Min(1)Long domainId,@RequestParam(required=false)String keyword,@RequestParam(required=false)CatalogAssetStatus status,@RequestParam(defaultValue="0")@Min(0)int page,@RequestParam(defaultValue="20")@Min(1)@Max(200)int size){var p=s.capabilities(domainId,keyword,status,page,size);return new Page(p.items().stream().map(Response::from).toList(),page,size,p.totalElements());}@PutMapping("/{id}")public Response update(@PathVariable@Min(1)long id,@Valid@RequestBody Update r,@RequestHeader("X-Operator")@NotBlank@Size(max=100)String a){return Response.from(s.updateCapability(id,r.capabilityName,r.description,r.ownerCode,r.status,r.rowVersion,a));}
public record Create(@Positive long domainId,@NotBlank@Size(max=128)@Pattern(regexp="^[a-z][a-z0-9]*(?:[._-][a-z0-9]+)*$")String capabilityCode,@NotBlank@Size(max=200)String capabilityName,@Size(max=1000)String description,@NotBlank@Size(max=100)String ownerCode){}public record Update(@NotBlank@Size(max=200)String capabilityName,@Size(max=1000)String description,@NotBlank@Size(max=100)String ownerCode,@NotNull CatalogAssetStatus status,@PositiveOrZero long rowVersion){}public record Response(long id,long domainId,String capabilityCode,String capabilityName,String description,String ownerCode,CatalogAssetStatus status,long rowVersion,Instant createdAt,Instant updatedAt){static Response from(CanonicalCapability c){return new Response(c.id(),c.domainId(),c.capabilityCode().value(),c.capabilityName(),c.description(),c.ownerCode(),c.status(),c.rowVersion(),c.createdAt(),c.updatedAt());}}public record Page(List<Response>items,int page,int size,long totalElements){}
}
